def build(output):
 output=Path(output);output.mkdir(parents=True,exist_ok=True)
 def opaque(x):return hashlib.sha256(('reliability-v1|'+x).encode()).hexdigest()[:24]
 cases=[];labels={}
 for lang,rows in DATA.items():
  for index,(group,interest,source,correct,fault) in enumerate(rows):
   category=CATEGORIES[index];feed=opaque(group+lang);aid=opaque(group+lang+'source');other=opaque(group+lang+'other')
   extra={'en':'Use two cups of flour to bake the cake.','fr':'Utilisez deux tasses de farine pour préparer le gâteau.','ar':'استخدم كوبين من الدقيق لتحضير الكعكة.'}[lang]
   articles=[{'id':aid,'feedId':feed,'text':source,'publishedAt':'2026-11-14T10:05:00Z','completeness':'complete'}]
   if category in ('citation','relevance'):articles.append({'id':other,'feedId':feed,'text':extra,'publishedAt':'2026-11-14T10:06:00Z','completeness':'complete'})
   prior=[]
   if category=='repetition':prior=[{'id':opaque('prior'+lang),'at':'2026-11-14T09:30:00Z','headline':'','body':fault}]
   for is_fault in (False,True):
    identity=opaque(group+lang+str(is_fault));body=fault if is_fault else correct
    items=[{'headline':'','body':body,'sourceIds':[other if is_fault and category=='citation' else aid]}]
    if is_fault and category=='relevance':items=[{'headline':'','body':correct,'sourceIds':[aid]},{'headline':'','body':fault,'sourceIds':[other]}]
    c={'id':identity,'feedId':feed,'language':lang,'interest':interest,'windowStart':'2026-11-14T10:00:00Z','windowEnd':'2026-11-14T10:30:00Z','frozenAt':'2026-11-14T10:31:00Z','publishedAt':'2026-11-14T10:31:00Z','evidenceScope':'all_eligible_frozen_input','evidenceComplete':True,'articles':copy.deepcopy(articles),'prior':prior,'items':items,'pipelineStatus':'published','sourceLabel':'offline-controlled-sources','limitations':[]}
    cases.append(c)
    labels[identity]={'measurementClass':'synthetic_fault_injection','language':lang,'eventGroup':group,'isFault':is_fault,'category':category if is_fault else None,'expected':{k:(1 if is_fault and k==category else (None if is_fault else 0)) for k in CATEGORIES},'scoringMask':'All seven negative categories for known-correct controls; primary injected category for faults. Secondary consequences of a mutation are not asserted negative.','evidence':[{'sourceId':a['id'],'quote':a['text'],'sha256':hashlib.sha256(a['text'].encode()).hexdigest()} for a in articles],'labelOrigin':'source-grounded AI-curated construction; independently inspected source assertions and controlled transformation, not a tested-judge label or human gold','transformation':category if is_fault else 'legitimate_paraphrase_or_necessary_update','rationale':{'factual':'The source states 120, not 210.','citation':'The cited recipe source does not support the library grant, which is established in another source.','coverage':'Mandatory evacuation includes two named districts; the candidate silently omits Bayshore.','relevance':'The second item is a recipe explicitly excluded by the feed interest.','repetition':'The unchanged closure was already communicated; the genuinely new shuttle development is absent.','temporal':'The scheduled meeting date is 18 November, not 19 November.','language':'The candidate is in a different language from the requested output.'}[category] if is_fault else 'Every material statement is established by the retained text; wording may differ. All interest-essential new developments are covered. Older bridge closure is history context, while the newly announced shuttle is a necessary update.'}
 random.Random(20261114).shuffle(cases)
 for name,value in [('blind-controls.json',cases),('control-labels.json',labels)]:
  p=output/name
  if p.exists():assert json.loads(p.read_text(encoding='utf-8'))==value,'Immutable dataset differs'
  else:p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 manifest={'cases':len(cases),'faults':sum(x['isFault'] for x in labels.values()),'controls':sum(not x['isFault'] for x in labels.values()),'eventGroups':7,'languages':['en','ar','fr'],'files':{n:hashlib.sha256((output/n).read_bytes()).hexdigest() for n in ['blind-controls.json','control-labels.json']},'scoringMask':'target-category positives and all-category negatives on correct controls; no assumptions that collateral consequences of a mutation are negative','independence':'Matched variants and translations share event groups; 42 cases are not 42 independent real-world events.'}
 (output/'controls-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8');print(json.dumps(manifest))
if __name__=='__main__':
 import sys
 build(sys.argv[1])
